import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    if m > n:
        print(-1)
        return
    lo, hi = max(a), sum(a)
    while lo < hi:
        mid = (lo + hi) // 2
        blocks, cur = 1, 0
        for x in a:
            if cur + x > mid:
                blocks += 1
                cur = x
            else:
                cur += x
        if blocks <= m:
            hi = mid
        else:
            lo = mid + 1
    print(lo)

